mapper.select:
select id, club_id, late_threshold, leave_early_threshold, absence_threshold, created_time, updated_time
from attendance_rules
where club_id = #{clubId}

mapper.insert:
insert into attendance_rules (
  club_id, late_threshold, leave_early_threshold, absence_threshold
) values (
  #{clubId}, #{lateThreshold}, #{leaveEarlyThreshold}, #{absenceThreshold}
)

mapper.update:
update attendance_rules
set late_threshold = #{lateThreshold},
    leave_early_threshold = #{leaveEarlyThreshold},
    absence_threshold = #{absenceThreshold}
where club_id = #{clubId}
